// Package autocomplete предоставляет сервис автодополнения поисковых запросов,
// основанный на префиксном дереве (trie) с учётом популярности запросов.
package autocomplete

import (
	"sort"
	"sync"
)

// TrieNode представляет узел префиксного дерева.
// Каждый узел хранит:
//   - children: карту дочерних узлов, где ключ — символ, значение — указатель на дочерний узел
//   - isEnd: флаг, указывающий, что данный узел является концом какого-либо запроса
//   - popularity: числовое значение популярности запроса, заканчивающегося в этом узле
//   - word: строка запроса, если узел является концом запроса (для быстрого возврата результата)
type TrieNode struct {
	children   map[rune]*TrieNode
	isEnd      bool
	popularity int
	word       string
}

// AutocompleteService — основной сервис автодополнения.
// Он использует префиксное дерево для хранения запросов и их популярности.
// Все операции потокобезопасны благодаря мьютексу.
type AutocompleteService struct {
	root *TrieNode
	mu   sync.RWMutex
}

// NewAutocompleteService создаёт новый экземпляр сервиса автодополнения.
// Возвращает указатель на инициализированный сервис с пустым префиксным деревом.
func NewAutocompleteService() *AutocompleteService {
	return &AutocompleteService{
		root: &TrieNode{
			children: make(map[rune]*TrieNode),
		},
	}
}

// AddQuery добавляет новый поисковый запрос в сервис автодополнения.
// Если запрос уже существует, его популярность увеличивается на 1.
// Если запроса ещё нет, он создаётся с начальной популярностью 1.
// Метод потокобезопасен.
func (s *AutocompleteService) AddQuery(query string) {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Переходим от корня дерева, создавая узлы по мере необходимости
	current := s.root
	for _, ch := range query {
		if current.children == nil {
			current.children = make(map[rune]*TrieNode)
		}
		if _, exists := current.children[ch]; !exists {
			current.children[ch] = &TrieNode{
				children: make(map[rune]*TrieNode),
			}
		}
		current = current.children[ch]
	}

	// Помечаем текущий узел как конец запроса
	current.isEnd = true
	current.word = query

	// Увеличиваем популярность запроса
	current.popularity++
}

