// Search выполняет поиск документов по заданному запросу.
// query — строка запроса, которую необходимо разбить на термины.
// limit — максимальное количество возвращаемых результатов.
// Возвращает срез идентификаторов документов, соответствующих запросу,
// или nil, если совпадений не найдено либо входные данные некорректны.
func (idx *Index) Search(query string, limit int) []int {
	// Разбиваем строку запроса на отдельные термины (слова).
	terms := tokenize(query)

	// Если после токенизации не осталось ни одного термина
	// или лимит результатов некорректен (меньше или равен нулю),
	// возвращаем nil, так как поиск невозможен.
	if len(terms) == 0 || limit <= 0 {
		return nil
	}

	// Получаем список документов (постинг-лист) для первого термина запроса.
	// Если такого термина нет в индексе, совпадений быть не может — возвращаем nil.
	result, ok := idx.postings[terms[0]]
	if !ok {
		return nil
	}

	// Последовательно пересекаем текущий результат с постинг-листами
	// для каждого оставшегося термина запроса.
	// Это реализует логику AND: документ должен содержать все термины запроса.
	for _, term := range terms[1:] {
		result = intersect(result, idx.postings[term])

		// Если после пересечения не осталось ни одного документа,
		// дальнейшие проверки бессмысленны — возвращаем nil.
		if len(result) == 0 {
			return nil
		}
	}

	// Если количество найденных документов превышает заданный лимит,
	// обрезаем результат до первых limit элементов.
	if len(result) > limit {
		result = result[:limit]
	}

	// Возвращаем итоговый список идентификаторов документов.
	return result
}
