/**
 * Функция переранжирования кандидатов с учётом лимитов по категориям и исключения уже купленных товаров.
 *
 * @param candidates - Список кандидатов для ранжирования.
 * @param purchased - Множество идентификаторов уже купленных товаров, которые нужно исключить.
 * @param maxPerCategory - Максимальное количество кандидатов, которые можно взять из одной категории.
 * @param limit - Общее максимальное количество кандидатов в итоговом списке.
 * @returns Отранжированный список кандидатов, удовлетворяющий всем ограничениям.
 */
export function rerank(
  candidates: Candidate[],
  purchased: Set<string>,
  maxPerCategory: number,
  limit: number,
): Candidate[] {
  // Создаём карту для подсчёта количества уже добавленных кандидатов по каждой категории.
  // Ключ — название категории, значение — сколько кандидатов из этой категории уже добавлено в результат.
  const perCategory = new Map<string, number>();

  // Инициализируем пустой массив для хранения итогового отранжированного списка.
  const result: Candidate[] = [];

  // Создаём копию массива кандидатов и сортируем его по убыванию оценки (score).
  // Это гарантирует, что мы будем рассматривать кандидатов от самых релевантных к менее релевантным.
  // Копия нужна, чтобы не мутировать исходный массив.
  for (const c of [...candidates].sort((a, b) => b.score - a.score)) {
    // Пропускаем кандидата, если его товар уже был куплен пользователем.
    if (purchased.has(c.itemId)) continue;

    // Получаем текущее количество кандидатов, уже добавленных из категории этого кандидата.
    // Если категория ещё не встречалась, используем 0 как начальное значение.
    const used = perCategory.get(c.category) ?? 0;

    // Пропускаем кандидата, если из его категории уже добавлено максимальное допустимое количество кандидатов.
    if (used >= maxPerCategory) continue;

    // Увеличиваем счётчик добавленных кандидатов для текущей категории.
    perCategory.set(c.category, used + 1);

    // Добавляем кандидата в итоговый список.
    result.push(c);

    // Если мы уже набрали нужное количество кандидатов (limit), прерываем цикл.
    if (result.length === limit) break;
  }

  // Возвращаем итоговый отранжированный список кандидатов.
  return result;
}
