fun planLoads(orders: List<Order>, capacityKg: Double): List<List<Order>> {
    // Проверяем, что вместимость грузовика положительная.
    // Если capacityKg <= 0, выбрасываем исключение, так как это не имеет физического смысла.
    require(capacityKg > 0) { "capacityKg must be positive" }

    // Находим заказы, вес которых превышает вместимость одного грузовика.
    // Такие заказы невозможно разместить ни в одном грузовике, поэтому сразу выбрасываем ошибку.
    val oversized = orders.filter { it.weightKg > capacityKg }
    if (oversized.isNotEmpty()) {
        throw IllegalArgumentException("orders exceed capacity: ${oversized.map { it.id }}")
    }

    // Список грузовиков (каждый грузовик — это список заказов).
    val loads = mutableListOf<MutableList<Order>>()
    // Список оставшейся свободной вместимости для каждого грузовика.
    // Индексы в loads и free соответствуют друг другу.
    val free = mutableListOf<Double>()

    // Сортируем заказы по убыванию веса.
    // Это эвристика "First Fit Decreasing" (FFD), которая обычно даёт хорошее приближение
    // к оптимальному решению задачи упаковки в контейнеры (bin packing).
    for (order in orders.sortedByDescending { it.weightKg }) {
        // Ищем первый грузовик, в который ещё помещается текущий заказ.
        val i = free.indexOfFirst { it >= order.weightKg }

        if (i >= 0) {
            // Если такой грузовик найден, добавляем заказ в него.
            loads[i].add(order)
            // Уменьшаем оставшуюся вместимость этого грузовика на вес добавленного заказа.
            free[i] -= order.weightKg
        } else {
            // Если ни в один существующий грузовик заказ не помещается,
            // создаём новый грузовик и кладём туда этот заказ.
            loads.add(mutableListOf(order))
            // Инициализируем оставшуюся вместимость нового грузовика.
            free.add(capacityKg - order.weightKg)
        }
    }

    // Возвращаем список грузовиков, каждый из которых содержит список заказов.
    return loads
}
